<template>
  <view class="danmaku-container">
    <view
      class="danmaku-track"
      v-for="(track, trackIndex) in tracks"
      :key="trackIndex"
    >
      <view
        class="danmaku-item"
        v-for="danmaku in track"
        :key="danmaku.id"
        :style="{
          transform: `translateX(${danmaku.x}px)`,
          animationDuration: `${danmaku.duration}s`,
        }"
        :class="{ 'danmaku-moving': danmaku.isMoving }"
      >
        {{ danmaku.content }}
      </view>
    </view>
  </view>
</template>

<script setup>
  import { ref, onMounted, onUnmounted } from 'vue'

  // 模拟后端数据
  const mockDanmakuData = [
    ['这是第一批弹幕1', '欢迎来到直播间！', '主播好棒啊', '666666', '点赞点赞'],
    ['这是第二批弹幕1', '太精彩了！', '继续加油', '支持主播', '笑死我了哈哈'],
    ['这是第三批弹幕1', '真的很有趣', '学到了', '感谢分享', '下次还来看'],
  ]

  // 组件数据
  const tracks = ref([[], [], []]) // 3个轨道
  const danmakuQueue = ref([]) // 弹幕队列
  const currentBatchIndex = ref(0) // 当前批次索引
  const containerWidth = ref(375) // 容器宽度，默认375px
  const isLastDanmakuShown = ref(false) // 标记最后一条弹幕是否已显示

  // 弹幕ID计数器
  let danmakuId = 0

  // 创建弹幕对象
  const createDanmaku = (content) => {
    return {
      id: ++danmakuId,
      content,
      x: containerWidth.value,
      duration: Math.random() * 3 + 5, // 5-8秒随机时长
      isMoving: false,
      trackIndex: -1,
    }
  }

  // 从后端获取弹幕数据（模拟）
  const fetchDanmakuData = async () => {
    console.log('正在获取新的弹幕数据...')

    // 模拟网络延迟
    await new Promise((resolve) => setTimeout(resolve, 500))

    const batchIndex = currentBatchIndex.value % mockDanmakuData.length
    const newData = mockDanmakuData[batchIndex]

    console.log(`获取第${currentBatchIndex.value + 1}批弹幕:`, newData)

    // 将新数据添加到队列
    newData.forEach((content) => {
      danmakuQueue.value.push(createDanmaku(content))
    })

    currentBatchIndex.value++
    isLastDanmakuShown.value = false
  }

  // 寻找可用轨道
  const findAvailableTrack = () => {
    for (let i = 0; i < tracks.value.length; i++) {
      const track = tracks.value[i]
      if (track.length === 0) {
        return i
      }

      // 检查轨道最后一个弹幕是否已经移动了足够距离
      const lastDanmaku = track[track.length - 1]
      if (lastDanmaku && lastDanmaku.x < containerWidth.value - 150) {
        return i
      }
    }
    return -1
  }

  // 显示弹幕
  const showDanmaku = () => {
    if (danmakuQueue.value.length === 0) return

    const availableTrack = findAvailableTrack()
    if (availableTrack === -1) return

    const danmaku = danmakuQueue.value.shift()
    danmaku.trackIndex = availableTrack
    tracks.value[availableTrack].push(danmaku)

    // 启动动画
    setTimeout(() => {
      danmaku.isMoving = true
      danmaku.x = -200 // 移动到左侧屏幕外
    }, 50)

    // 动画结束后清理
    setTimeout(() => {
      const trackDanmakus = tracks.value[availableTrack]
      const index = trackDanmakus.findIndex((item) => item.id === danmaku.id)
      if (index !== -1) {
        trackDanmakus.splice(index, 1)
      }
    }, danmaku.duration * 1000)

    // 检查是否是最后一条弹幕
    if (danmakuQueue.value.length === 0 && !isLastDanmakuShown.value) {
      isLastDanmakuShown.value = true
      // 延迟一段时间后获取新弹幕
      setTimeout(() => {
        fetchDanmakuData()
      }, 2000)
    }
  }

  // 定时器
  let showTimer = null

  // 启动弹幕展示
  const startDanmaku = () => {
    showTimer = setInterval(showDanmaku, 800) // 每0.8秒尝试显示一条弹幕
  }

  // 停止弹幕展示
  const stopDanmaku = () => {
    if (showTimer) {
      clearInterval(showTimer)
      showTimer = null
    }
  }

  // 获取容器宽度
  const getContainerWidth = () => {
    // 在真实的uniapp环境中，可以使用uni.getSystemInfo()获取屏幕宽度
    // 这里暂时使用固定值
    uni.getSystemInfo({
      success: (res) => {
        containerWidth.value = res.windowWidth
      },
    })
  }

  // 生命周期
  onMounted(async () => {
    getContainerWidth()
    await fetchDanmakuData()
    startDanmaku()
  })

  onUnmounted(() => {
    stopDanmaku()
  })

  // 暴露方法供父组件调用
  defineExpose({
    startDanmaku,
    stopDanmaku,
    fetchDanmakuData,
  })
</script>

